  for (const x of [7, 15, 23]) door(x, 7, 2, "north", "left");

  // ---- rear windows: 1 wide x 2 tall at y 15..16 and y 20..21, sills out on the yard side at z 1 ----
  for (const x of [6, 10, 14, 18]) for (const y0 of [15, 20]) {
